// #d9d257 (6a993d711bef8ed807d9d257) — одноразовая неоцениваемая практика: экраны ДО звонка, без расхода OpenAI.
// Кейсы CALL-008 (экран «פרטי לקוח לתרגול»), CALL-009 (предупреждение и обязательная галочка перед официальной).
// НЕ prod-safe: создаёт кандидата «QA-AUTO-CALL-1T-…» (link_only, без письма/SMS); кандидат не удаляется (правило проекта).
// Старт попыток/голосовой сессии обрывается страховкой blockCallStarts — звонков нет, официальная попытка не тратится.
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import {
  Candidate, ONE_TIME, createCandidateLink, launchCandidate, goToPractice, tap, scrollWidth, blockCallStarts,
} from './support';

test.describe.configure({ mode: 'serial' });

let cand: Candidate | undefined;
let blocked = { start: 0, voice: 0 };

test.afterAll(async () => {
  await cand?.browser.close();
});

test.describe('Звонок кандидата — одноразовая практика, экраны до звонка (#6a993d711bef8ed807d9d257)', () => {
  test('«פרטי לקוח לתרגול»: «התרגול אינו מוערך, אינו מופיע באף דוח ומוצע פעם אחת בלבד», 3 דקות, «להתחיל תרגול» + «לדלג ישר לשיחה הרשמית»; 390 и 1440 без горизонтальной прокрутки @desktop @data #6a993d711bef8ed807d9d257', async ({ asUser }) => {
    test.setTimeout(4 * 60_000);
    const business = await asUser('business');
    const name = `QA-AUTO-CALL-1T-${runStamp()}`;
    const link = await createCandidateLink(business, name);
    test.info().annotations.push({ type: 'test-data', description: `кандидат «${name}» (практика пропущена), не удаляется` });

    cand = await launchCandidate({ width: 390, height: 844 });
    const { page, counts } = cand;
    blocked = await blockCallStarts(page);
    await goToPractice(page, link);

    // Источник: AC2 / דרישה 1 «אינו מוערך ואינו מופיע בדוח»; S-15 — пояснение + одна главная кнопка.
    await expect(page.getByText(ONE_TIME.practiceNote)).toBeVisible();
    await expect(page.getByText('3 דקות')).toBeVisible();
    await expect(page.getByRole('button', { name: 'להתחיל תרגול' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'לדלג ישר לשיחה הרשמית' })).toBeVisible();
    let w = await scrollWidth(page);
    expect(w.sw, 'горизонтальная прокрутка на 390').toBeLessThanOrEqual(w.vw);

    await page.setViewportSize({ width: 1440, height: 900 });
    await expect(page.getByText(ONE_TIME.practiceNote)).toBeVisible();
    w = await scrollWidth(page);
    expect(w.sw, 'горизонтальная прокрутка на 1440').toBeLessThanOrEqual(w.vw);
    await page.setViewportSize({ width: 390, height: 844 });

    expect(counts.start + blocked.start, 'старт попытки без нажатия').toBe(0);
  });

  test('перед официальной: «השיחה הבאה היא השיחה הנספרת…», галочка «הבנתי שזה ניסיון חד-פעמי» не отмечена; «מוכן, מתחילים» без неё → «כדי להתחיל יש לאשר שזה ניסיון חד-פעמי.», старта нет @desktop @data #6a993d711bef8ed807d9d257', async () => {
    test.setTimeout(2 * 60_000);
    expect(cand, 'нет состояния из предыдущего теста').toBeTruthy();
    const { page, counts } = cand!;

    await tap(page, 'לדלג ישר לשיחה הרשמית');
    await expect(page.getByText('פרטי לקוח לשיחה')).toBeVisible();
    // Источник: AC5 / דרישה 3 «אזהרה שהניסיון הרשמי חד-פעמי ונדרש אישור מפורש».
    await expect(page.getByText(ONE_TIME.officialWarn)).toBeVisible();
    await expect(page.getByText(ONE_TIME.officialRetryRule)).toBeVisible();
    const confirm = page.getByRole('checkbox', { name: ONE_TIME.confirm });
    await expect(confirm).not.toBeChecked();

    await tap(page, 'מוכן, מתחילים');
    await expect(page.getByText(ONE_TIME.confirmRequired)).toBeVisible();
    expect(counts.start, 'candidate_start_attempt без галочки').toBe(0);
    expect(counts.voice, 'start-voice-session без галочки').toBe(0);

    await page.setViewportSize({ width: 1440, height: 900 });
    await expect(page.getByText(ONE_TIME.officialWarn)).toBeVisible();
    const w = await scrollWidth(page);
    expect(w.sw, 'горизонтальная прокрутка на 1440').toBeLessThanOrEqual(w.vw);
  });
});
